const body = $input.first().json.body || $input.first().json;

const employeeEmail = (body.email || body.employeeEmail || '').trim().toLowerCase();
const employeeId = (body.employeeId || 'EMP-' + Math.floor(1000 + Math.random() * 9000)).trim();

if (!employeeEmail || !employeeEmail.includes('@')) {
  throw new Error("[Validation Error] Email nhân viên không hợp lệ!");
}

// Sinh mật khẩu tạm ngẫu nhiên an toàn (10 ký tự: chữ hoa, chữ thường, số, ký tự đặc biệt)
const chars = 'abcdefghjkmnpqrstuvwxyzABCDEFGHJKMNPQRSTUVWXYZ23456789!@#$%';
let tempPassword = 'P@';
for (let i = 0; i < 8; i++) {
  tempPassword += chars.charAt(Math.floor(Math.random() * chars.length));
}

const resetToken = 'RST-' + Math.random().toString(36).substring(2, 10).toUpperCase();
const expiresAt = new Date(Date.now() + 15 * 60 * 1000).toISOString(); // Hết hạn sau 15 phút

return {
  employeeEmail,
  employeeId,
  tempPassword,
  resetToken,
  expiresAt,
  requestedAt: new Date().toISOString()
};

