const prev = $('Generate Temp Password & Token').first().json;
const aiRaw = $input.first().json;

let text = '';
if (aiRaw.candidates?.[0]?.content?.parts?.[0]?.text) {
  text = aiRaw.candidates[0].content.parts[0].text;
} else {
  text = JSON.stringify(aiRaw);
}

text = text.replace(/```json\s*/gi, '').replace(/```\s*$/gi, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    emailSubject: `[IT HELPDESK] Mật khẩu tạm thời cho ${prev.employeeEmail}`,
    emailContent: `Kính gửi nhân viên, mật khẩu tạm của bạn là: ${prev.tempPassword}. Hết hạn sau 15 phút.`
  };
}

return {
  employeeEmail: prev.employeeEmail,
  employeeId: prev.employeeId,
  tempPassword: prev.tempPassword,
  resetToken: prev.resetToken,
  expiresAt: prev.expiresAt,
  emailSubject: parsed.emailSubject,
  emailContent: parsed.emailContent
};

